import axios from 'axios';

const API_URL = 'http://localhost:8080/api';

// Create axios instance with default config
const api = axios.create({
  baseURL: API_URL,
  headers: {
    'Content-Type': 'application/json',
  },
  withCredentials: true, // Important for handling cookies
});

// Add request interceptor for logging
api.interceptors.request.use(
  (config) => {
    console.log('Making request to:', config.url);
    console.log('Request data:', config.data);
    return config;
  },
  (error) => {
    console.error('Request error:', error);
    return Promise.reject(error);
  }
);

// Add response interceptor for better error handling
api.interceptors.response.use(
  (response) => {
    console.log('Response received:', response.data);
    return response;
  },
  (error) => {
    console.error('Response error:', {
      status: error.response?.status,
      statusText: error.response?.statusText,
      data: error.response?.data,
      headers: error.response?.headers,
      config: {
        url: error.config?.url,
        method: error.config?.method,
        data: error.config?.data
      }
    });
    return Promise.reject(error);
  }
);

export const registerUser = async (userData) => {
  try {
    console.log('Sending registration request with:', { 
      email: userData.email,
      firstName: userData.firstName,
      lastName: userData.lastName,
      password: '***' // Don't log the actual password
    });

    const response = await api.post('/auth/register', userData);
    console.log('Registration response received:', response.data);
    return response.data;
  } catch (error) {
    console.error('Registration error details:', {
      status: error.response?.status,
      statusText: error.response?.statusText,
      data: error.response?.data,
      message: error.message
    });

    if (error.response?.status === 400) {
      throw new Error(error.response.data || 'Invalid registration data. Please check your input.');
    } else if (error.response?.data?.message) {
      throw new Error(error.response.data.message);
    } else if (error.message === 'Network Error') {
      throw new Error('Unable to connect to the server. Please check your internet connection.');
    } else {
      throw new Error('An unexpected error occurred during registration. Please try again later.');
    }
  }
};

export const loginUser = async (credentials) => {
  try {
    console.log('Sending login request with credentials:', { 
      email: credentials.email,
      password: '***' // Don't log the actual password
    });

    const response = await api.post('/auth/login', {
      email: credentials.email,
      password: credentials.password
    });

    console.log('Login response received:', response.data);
    return response.data;
  } catch (error) {
    // Log the complete error for debugging
    console.error('Complete error object:', {
      name: error.name,
      message: error.message,
      stack: error.stack,
      response: error.response ? {
        status: error.response.status,
        statusText: error.response.statusText,
        data: error.response.data,
        headers: error.response.headers
      } : null,
      request: error.request ? {
        method: error.request.method,
        url: error.request.url,
        headers: error.request.headers
      } : null
    });

    // Check if we have a response from the server
    if (error.response) {
      if (error.response.status === 401) {
        throw new Error('Invalid email or password. Please try again.');
      }

      // If the server sent a message, use it
      if (error.response.data && error.response.data.message) {
        throw new Error(error.response.data.message);
      }
    }

    // Handle network errors
    if (error.message === 'Network Error') {
      throw new Error('Unable to connect to the server. Please check your internet connection.');
    }

    // Handle request setup errors
    if (error.request) {
      throw new Error('The request was made but no response was received.');
    }

    // If we get here, it's an unexpected error
    throw new Error('An unexpected error occurred. Please try again later.');
  }
};

// Add a function to check server status
export const checkServerStatus = async () => {
  try {
    console.log('Checking server status...');
    const response = await api.get('/health');
    console.log('Server status response:', response.data);
    return response.data;
  } catch (error) {
    console.error('Server status check failed:', {
      status: error.response?.status,
      statusText: error.response?.statusText,
      data: error.response?.data,
      message: error.message
    });
    throw error;
  }
};
